const grpc = require('@grpc/grpc-js');
const { DeviceAuditLog, Device } = require('../models');
const { verifyMetadataAuth } = require('../auth');

function ingestDiagnostics(call, callback) {
  const logs = [];
  let targetDeviceId = null;

  call.on('data', async (chunk) => {
    targetDeviceId = chunk.deviceId;
    logs.push({ logLine: chunk.logLine, level: chunk.level, timestamp: chunk.timestamp });
  });

  call.on('end', async () => {
    const user = await verifyMetadataAuth(call.metadata);
    if (!user) return callback({ code: grpc.status.UNAUTHENTICATED });

    const device = await Device.findOne({ where: { id: targetDeviceId, ownerId: user.id } });
    if (!device) {
      return callback({ code: grpc.status.PERMISSION_DENIED, message: 'Unauthorized device' });
    }

    if (targetDeviceId && logs.length) {
      await DeviceAuditLog.bulkCreate(logs.map(l => ({ ...l, deviceId: targetDeviceId })));
    }
    callback(null, { ingestedCount: logs.length });
  });
}
